class Component extends DCLogic {
 constructor(p){super(p);this.state={stage:'offer',hours:'4',attended:'yes',notice:'',error:''};}
 renderVals(){const s=this.state;const set=stage=>()=>this.setState({stage,notice:'',error:''});const labels={offer:['Возможность','Ассистент на Арт-субботе'],pending:['Отклик отправлен','Координатор рассмотрит отклик'],review:['Вид координатора','Согласовать первый выход'],approved:['Координатор согласовал','Подтверди, что придёшь'],confirmed:['Выход подтверждён','Тебя ждут 24 октября'],attendance:['Вид координатора','Как прошло участие?'],completed:['Участие состоялось','Спасибо за помощь'],absent:['Неучастие отмечено','Участие не состоялось'],withdrawn:['Отклик отозван','Можно выбрать другой вариант']};let index={offer:0,pending:1,review:1,approved:2,confirmed:3,attendance:3,completed:4,absent:3,withdrawn:0}[s.stage];return {modes:[['offer','Возможность'],['pending','Отклик'],['approved','Согласовано'],['confirmed','Подтверждено'],['completed','Участвовал']].map(([id,title])=>({title,cls:s.stage===id?'is-on':'',pick:set(id)})),stageLabel:labels[s.stage][0],heroTitle:labels[s.stage][1],offer:s.stage==='offer',pending:s.stage==='pending',reviewing:s.stage==='review',approved:s.stage==='approved',confirmed:s.stage==='confirmed',attendance:s.stage==='attendance',completed:s.stage==='completed',withdrawn:s.stage==='withdrawn'||s.stage==='absent',startAttendance:set('attendance'),apply:set('pending'),review:set('review'),approve:set('approved'),confirm:set('confirmed'),withdraw:set('withdrawn'),again:set('offer'),defer:()=>this.setState({stage:'pending',notice:'Нужно обсудить подготовку. Отклик остаётся на рассмотрении.'}),steps:['Возможность','Отклик','Согласование','Подтверждение','Участие'].map((title,i)=>({title,number:String(i+1),cls:'step'+(i<=index?' is-on':'')})),didAttend:s.attended==='yes',didNotAttend:s.attended==='no',hours:s.hours,attended:s.attended,changeHours:e=>this.setState({hours:e.target.value}),changeAttendance:e=>this.setState({attended:e.target.value}),complete:()=>{if(s.attended==='no'){this.setState({stage:'absent',notice:'Неучастие отмечено. Часы не начислены.'});return;}if(!Number.isFinite(Number(s.hours))||Number(s.hours)<0||Number(s.hours)>12||s.hours===''){this.setState({error:'Укажите длительность от 0 до 12 часов.'});return;}this.setState({stage:'completed',notice:s.hours+' часа подтверждены координатором.',error:''});},notice:s.notice,hasError:!!s.error,error:s.error};}
}
